// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title AttestationRegistry
 * @author Expert Solidity Engineer
 * @notice A decentralized registry for typed attestations on EVM-compatible chains like Camp (BaseCAMP).
 * Issuers sign attestations off-chain using EIP-712, and anyone can submit them on-chain.
 * The registry supports schemas, role-based access control, revocation by issuer or subject,
 * optional fees, and pausing functionality.
 */
contract AttestationRegistry is AccessControl, Pausable, EIP712 {
    using ECDSA for bytes32;

    // --- Roles ---

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant SCHEMA_MANAGER_ROLE = keccak256("SCHEMA_MANAGER_ROLE");
    bytes32 public constant FEE_MANAGER_ROLE = keccak256("FEE_MANAGER_ROLE");
    // DEFAULT_ADMIN_ROLE is used for role management and fee withdrawal.

    // --- Errors ---

    error SchemaNotFound();
    error SchemaExists();
    error SchemaIsPaused();
    error InvalidFee();
    error AttestationExpired();
    error InvalidNonce();
    error AttestationIdExists();
    error AttestationNotFound();
    error AlreadyRevoked();
    error NotAuthorized();
    error InvalidSignature();
    error NoFeesToWithdraw();
    error TransferFailed();
    error ZeroAddress();

    // --- Structs ---

    /**
     * @dev Defines the structure and rules for a type of attestation.
     * @param name A human-readable name for the schema.
     * @param definition A string defining the schema, e.g., a JSON schema.
     * @param revocableBySubject If true, the subject of an attestation can revoke it.
     * @param paused If true, no new attestations for this schema can be submitted.
     */
    struct Schema {
        string name;
        string definition;
        bool revocableBySubject;
        bool paused;
    }

    /**
     * @dev Represents an on-chain attestation.
     * @param schemaId The ID of the schema this attestation conforms to.
     * @param issuer The address that issued and signed the attestation.
     * @param subject The address that is the subject of the attestation.
     * @param expirationTime The Unix timestamp after which the attestation is no longer valid. 0 for no expiration.
     * @param data The arbitrary data of the attestation, conforming to the schema.
     * @param metadataURI A URI pointing to off-chain metadata, e.g., an IPFS CID.
     * @param revoked A flag indicating if the attestation has been revoked.
     */
    struct Attestation {
        bytes32 schemaId;
        address issuer;
        address subject;
        uint256 expirationTime;
        bytes data;
        string metadataURI;
        bool revoked;
    }

    /**
     * @dev The data structure that is signed by the issuer off-chain according to EIP-712.
     * @param schemaId The ID of the schema.
     * @param subject The address receiving the attestation.
     * @param expirationTime The expiration timestamp. 0 means no expiration.
     * @param data The attestation data.
     * @param metadataURI The metadata URI.
     * @param nonce The issuer's nonce to prevent replay attacks.
     */
    struct AttestationRequest {
        bytes32 schemaId;
        address subject;
        uint256 expirationTime;
        bytes data;
        string metadataURI;
        uint256 nonce;
    }

    // --- EIP-712 ---

    bytes32 private constant ATTESTATION_REQUEST_TYPEHASH = keccak256(
        "AttestationRequest(bytes32 schemaId,address subject,uint256 expirationTime,bytes data,string metadataURI,uint256 nonce)"
    );

    // --- State Variables ---

    mapping(bytes32 => Schema) public schemas;
    mapping(bytes32 => Attestation) public attestations;
    mapping(address => uint256) public nonces;
    uint256 public attestationFee;

    // --- Events ---

    event SchemaCreated(bytes32 indexed schemaId, string name, bool revocableBySubject);
    event SchemaPausedStateChanged(bytes32 indexed schemaId, bool isPaused);
    event Attested(bytes32 attestationId, address indexed issuer, address indexed subject, bytes32 indexed schemaId);
    event Revoked(bytes32 indexed attestationId, address revoker);
    event FeeSet(uint256 newFee);
    event FeeWithdrawn(address indexed to, uint256 amount);

    // --- Constructor ---

    /**
     * @dev Sets up the contract, EIP-712 domain, and initial roles.
     * @param name The EIP-712 domain name (e.g., "AttestationRegistry").
     * @param version The EIP-712 domain version (e.g., "1").
     */
    constructor(string memory name, string memory version) EIP712(name, version) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        _grantRole(SCHEMA_MANAGER_ROLE, msg.sender);
        _grantRole(FEE_MANAGER_ROLE, msg.sender);
    }

    // --- Schema Management ---

    /**
     * @dev Creates a new attestation schema.
     * @param schemaId A unique identifier for the schema.
     * @param name A human-readable name for the schema.
     * @param definition A string defining the schema's data structure.
     * @param revocableBySubject Whether subjects can revoke attestations of this type.
     */
    function createSchema(
        bytes32 schemaId,
        string calldata name,
        string calldata definition,
        bool revocableBySubject
    ) external onlyRole(SCHEMA_MANAGER_ROLE) {
        if (bytes(schemas[schemaId].name).length != 0) revert SchemaExists();

        schemas[schemaId] = Schema({
            name: name,
            definition: definition,
            revocableBySubject: revocableBySubject,
            paused: false
        });

        emit SchemaCreated(schemaId, name, revocableBySubject);
    }

    /**
     * @dev Pauses or unpauses a schema, preventing or allowing new attestations.
     * @param schemaId The ID of the schema to update.
     * @param isPaused The new paused state.
     */
    function setSchemaPaused(bytes32 schemaId, bool isPaused) external onlyRole(SCHEMA_MANAGER_ROLE) {
        if (bytes(schemas[schemaId].name).length == 0) revert SchemaNotFound();
        schemas[schemaId].paused = isPaused;
        emit SchemaPausedStateChanged(schemaId, isPaused);
    }

    // --- Attestation Lifecycle ---

    /**
     * @dev Submits an attestation on-chain by verifying an issuer's EIP-712 signature.
     * This function is payable to cover an optional attestation fee.
     * @param request The AttestationRequest data that was signed by the issuer.
     * @param signature The EIP-712 signature from the issuer.
     */
    function submitAttestation(
        AttestationRequest calldata request,
        bytes calldata signature
    ) external payable whenNotPaused {
        if (msg.value < attestationFee) revert InvalidFee();

        Schema storage schema = schemas[request.schemaId];
        if (bytes(schema.name).length == 0) revert SchemaNotFound();
        if (schema.paused) revert SchemaIsPaused();

        if (request.expirationTime != 0 && request.expirationTime <= block.timestamp) {
            revert AttestationExpired();
        }

        bytes32 digest = _hashAttestationRequest(request);
        address issuer = digest.recover(signature);
        if (issuer == address(0)) revert InvalidSignature();
        if (request.nonce != nonces[issuer]) revert InvalidNonce();

        nonces[issuer]++;

        bytes32 attestationId = getAttestationId(issuer, request.schemaId, request.nonce);
        if (attestations[attestationId].issuer != address(0)) revert AttestationIdExists();

        attestations[attestationId] = Attestation({
            schemaId: request.schemaId,
            issuer: issuer,
            subject: request.subject,
            expirationTime: request.expirationTime,
            data: request.data,
            metadataURI: request.metadataURI,
            revoked: false
        });

        emit Attested(attestationId, issuer, request.subject, request.schemaId);
    }

    /**
     * @dev Revokes an existing attestation.
     * Can be called by the issuer, or by the subject if the schema allows it.
     * @param attestationId The ID of the attestation to revoke.
     */
    function revokeAttestation(bytes32 attestationId) external whenNotPaused {
        Attestation storage att = attestations[attestationId];
        if (att.issuer == address(0)) revert AttestationNotFound();
        if (att.revoked) revert AlreadyRevoked();

        bool isIssuer = msg.sender == att.issuer;
        bool canSubjectRevoke = schemas[att.schemaId].revocableBySubject && (msg.sender == att.subject);

        if (!isIssuer && !canSubjectRevoke) revert NotAuthorized();

        att.revoked = true;
        emit Revoked(attestationId, msg.sender);
    }

    // --- Fee Management ---

    /**
     * @dev Sets the fee required to submit an attestation.
     * @param newFee The new fee in wei.
     */
    function setFee(uint256 newFee) external onlyRole(FEE_MANAGER_ROLE) {
        attestationFee = newFee;
        emit FeeSet(newFee);
    }

    /**
     * @dev Withdraws accumulated fees from the contract.
     * @param to The address to receive the fees.
     */
    function withdrawFees(address payable to) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = address(this).balance;
        if (amount == 0) revert NoFeesToWithdraw();

        (bool success, ) = to.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit FeeWithdrawn(to, amount);
    }

    // --- Pausability ---

    /**
     * @dev Pauses critical functions of the contract.
     * Can only be called by an account with the PAUSER_ROLE.
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @dev Unpauses the contract.
     * Can only be called by an account with the PAUSER_ROLE.
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // --- View Functions ---

    /**
     * @dev Checks if an attestation is currently valid (exists, not revoked, not expired).
     * @param attestationId The ID of the attestation to check.
     * @return A boolean indicating validity.
     */
    function isAttestationValid(bytes32 attestationId) public view returns (bool) {
        Attestation memory att = attestations[attestationId];
        if (att.issuer == address(0) || att.revoked) {
            return false;
        }
        return att.expirationTime == 0 || att.expirationTime > block.timestamp;
    }

    /**
     * @dev Computes the unique ID for an attestation based on its core properties.
     * This can be used off-chain to predict the ID. The nonce ensures uniqueness per issuance.
     * @param issuer The address of the issuer.
     * @param schemaId The ID of the schema.
     * @param nonce The nonce used for the attestation.
     * @return The computed attestation ID.
     */
    function getAttestationId(address issuer, bytes32 schemaId, uint256 nonce) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(issuer, schemaId, nonce));
    }

    // --- EIP-712 Helpers ---

    /**
     * @dev Hashes the AttestationRequest struct according to the EIP-712 standard.
     * @param request The attestation request to hash.
     * @return The EIP-712 typed data hash.
     */
    function _hashAttestationRequest(AttestationRequest calldata request) internal view returns (bytes32) {
        return _hashTypedDataV4(keccak256(abi.encode(
            ATTESTATION_REQUEST_TYPEHASH,
            request.schemaId,
            request.subject,
            request.expirationTime,
            keccak256(request.data),
            keccak256(bytes(request.metadataURI)),
            request.nonce
        )));
    }
}

